"use strict";

// The NEGATIVE control that makes RWF-027 sound rather than merely
// aggressive. Every factory here ALSO has more than one ending -- so every
// one of them reaches the new multi-path summary -- but each keeps at least
// one ending that leaves the class definition able to complete.
//
// So `module.exports = safeOp` really IS reached on every load, and
// withdrawing authority from any of these would be an OVERREACH: reporting
// a class definition that demonstrably completes as fatal. Proven
// in-process, with assertions, in the ground-truth fixture's `c.js`.

function dangerousOp(input) {
  return "EXPLODED:" + input;
}

function safeOp(input) {
  return "safe:" + input;
}

class Base {}

// throw + CONSTRUCTABLE. This is the P0-B non-overreach control: one
// throwing path must never be promoted to an all-path conclusion.
function throwOrBase(flag) {
  if (flag) {
    throw new Error("boom");
  }
  return Base;
}

// invalid + CONSTRUCTABLE.
function invalidOrBase(flag) {
  if (flag) {
    return 1;
  }
  return Base;
}

// invalid + VALID NULL. `class C extends null {}` is LEGAL, and treating
// `null` as just another non-constructor is the single worst available
// mistake here -- so it is a control in its own right.
function invalidOrNull(flag) {
  if (flag) {
    return 1;
  }
  return null;
}

// throw + valid null.
function throwOrNull(flag) {
  if (flag) {
    throw new Error("boom");
  }
  return null;
}

// invalid + UNKNOWN. One unclassifiable ending refuses the whole summary:
// unsupported semantics degrade to unknown, never to false certainty.
function invalidOrUnknown(flag) {
  if (flag) {
    return 1;
  }
  return require("./danger").explode;
}

// A nested `if` whose VALID leaf is two levels down. If the descent lost
// that leaf, this module would be withdrawn and the loss would be silent.
function nestedWithValidLeaf(a, b) {
  if (a) {
    if (b) return Base;
    throw new Error("boom");
  }
  return 2;
}

// Unmodeled control flow poisons the summary: the collector must refuse a
// loop outright rather than reason about it. Deliberately ALSO completable
// at runtime (`loopBodied(true)` returns `Base`), so this module's claim
// that `safeOp` is genuinely reached on every load stays true -- a control
// that aborted at runtime would prove nothing about a NOT_AFFECTED verdict.
function loopBodied(flag) {
  while (flag) {
    return Base;
  }
  return 2;
}

// All endings fatal, but the class definition is DEFERRED inside a function
// nobody calls at module scope -- so no module-time cutoff may be created.
function allBad(flag) {
  if (flag) return 1;
  return 2;
}

function configure() {
  class Deferred extends allBad(true) {}
  return Deferred;
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;

  class FromThrowOrBase extends throwOrBase(false) {}
  class FromInvalidOrBase extends invalidOrBase(false) {}
  class FromInvalidOrNull extends invalidOrNull(false) {}
  class FromThrowOrNull extends throwOrNull(false) {}
  class FromInvalidOrUnknown extends invalidOrUnknown(false) {}
  class FromNestedValid extends nestedWithValidLeaf(true, true) {}
  class FromLoop extends loopBodied(true) {}

  void FromThrowOrBase;
  void FromInvalidOrBase;
  void FromInvalidOrNull;
  void FromThrowOrNull;
  void FromInvalidOrUnknown;
  void FromNestedValid;
  void FromLoop;
  void configure;
}

module.exports = safeOp;
